// Generated by OSL (@osl/backend-drizzle-next). Test hooks: a clock for timers and schedules, and the captured mailbox, the switch for the rule checks and the unbound probe. Routes mount these only when OSL_TEST_HOOKS=1.
// Do not edit: this file is rewritten on every osl generate.

import { asSystem, unboundRows } from "./db/client";
import { setRulesDisabled } from "./access";
import { runDueTimers, runSchedulesFor } from "./scheduling";
import { captured } from "./email";

/** Whether the hooks are on: never in production */
export function testHooksEnabled(): boolean {
  return process.env.OSL_TEST_HOOKS === "1";
}

/** The moment a hook runs at: the body's `now`, or the clock */
export function hookNow(body: unknown): Date {
  const raw = (body as { now?: unknown } | null)?.now;
  const parsed = typeof raw === "string" ? new Date(raw) : null;
  return parsed && !Number.isNaN(parsed.getTime()) ? parsed : new Date();
}

/** POST /api/osl-hooks/timers/run { now } */
export async function timersRun(body: unknown): Promise<{ ran: number }> {
  return { ran: await asSystem(() => runDueTimers(hookNow(body))) };
}

/** POST /api/osl-hooks/schedules/run { run, now }; null when nothing is scheduled under that action */
export async function schedulesRun(body: unknown): Promise<{ ran: number } | null> {
  const run = (body as { run?: unknown } | null)?.run;
  if (typeof run !== "string") return null;
  const ran = await asSystem(() => runSchedulesFor(run, hookNow(body)));
  return ran ? { ran } : null;
}

/** GET /api/osl-hooks/emails?to=&subject= : captured mail, newest last */
export function emailsSent(query: { to?: string; subject?: string }): { to: string; subject: string; text: string }[] {
  return captured
    .filter(e => (!query.to || e.to === query.to) && (!query.subject || e.subject.includes(query.subject)))
    .map(e => ({ to: e.to, subject: e.subject, text: e.text }));
}

/** POST /api/osl-hooks/rules/off and /on: switch the generated rule checks, so a walk can prove the policies alone hold */
export function rulesSwitch(off: boolean): { rules: "off" | "on" } {
  setRulesDisabled(off);
  return { rules: off ? "off" : "on" };
}

/** GET /api/osl-hooks/tenancy/unbound: what the app role reads of every tenant table with no tenant bound */
export function tenancyUnbound(): Promise<{ table: string; count: number; ids: string[] }[]> {
  return unboundRows();
}
